"""wininput — 模拟键鼠（SendInput 绝对坐标 + Unicode 文本）+ 窗口截图

用途：API 拿不到（风控）时，直接操作已经登录好的浏览器窗口（先截图看清 → 再点）。
  · focus_window(keyword)   找窗口并置前
  · click(x, y)             绝对坐标左键（屏幕坐标，支持多显示器）
  · scroll(n)               滚轮
  · key(vk) / type_text(s)  按键 / 打字（中文走 KEYEVENTF_UNICODE）
  · grab(path)              截整屏（虚拟桌面）到 png，供"看图"用
坐标一律用【虚拟桌面的绝对像素】，内部换算成 SendInput 的 0..65535 归一值。
"""
from __future__ import annotations

import ctypes
import time
from ctypes import wintypes

user32 = ctypes.WinDLL("user32", use_last_error=True)
gdi32 = ctypes.WinDLL("gdi32", use_last_error=True)

ULONG_PTR = ctypes.c_size_t
INPUT_KEYBOARD = 1
INPUT_MOUSE = 0
KEYEVENTF_KEYUP = 0x0002
KEYEVENTF_UNICODE = 0x0004
MOUSEEVENTF_MOVE = 0x0001
MOUSEEVENTF_ABSOLUTE = 0x8000
MOUSEEVENTF_LEFTDOWN = 0x0002
MOUSEEVENTF_LEFTUP = 0x0004
MOUSEEVENTF_WHEEL = 0x0800
SM_XVIRTUALSCREEN, SM_YVIRTUALSCREEN = 76, 77
SM_CXVIRTUALSCREEN, SM_CYVIRTUALSCREEN = 78, 79
SW_RESTORE = 9


class KEYBDINPUT(ctypes.Structure):
    _fields_ = [("wVk", wintypes.WORD), ("wScan", wintypes.WORD),
                ("dwFlags", wintypes.DWORD), ("time", wintypes.DWORD),
                ("dwExtraInfo", ULONG_PTR)]


class MOUSEINPUT(ctypes.Structure):
    _fields_ = [("dx", wintypes.LONG), ("dy", wintypes.LONG),
                ("mouseData", wintypes.DWORD), ("dwFlags", wintypes.DWORD),
                ("time", wintypes.DWORD), ("dwExtraInfo", ULONG_PTR)]


class _U(ctypes.Union):
    _fields_ = [("ki", KEYBDINPUT), ("mi", MOUSEINPUT), ("pad", ctypes.c_ubyte * 32)]


class INPUT(ctypes.Structure):
    _fields_ = [("type", wintypes.DWORD), ("u", _U)]


assert ctypes.sizeof(INPUT) == 40, ctypes.sizeof(INPUT)


def _send(*inputs):
    n = len(inputs)
    arr = (INPUT * n)(*inputs)
    return user32.SendInput(n, ctypes.byref(arr), ctypes.sizeof(INPUT))


def _ki(vk=0, scan=0, flags=0):
    i = INPUT(type=INPUT_KEYBOARD)
    i.u.ki = KEYBDINPUT(vk, scan, flags, 0, 0)
    return i


def _mi(dx=0, dy=0, flags=0, data=0):
    i = INPUT(type=INPUT_MOUSE)
    i.u.mi = MOUSEINPUT(dx, dy, data, flags, 0, 0)
    return i


def screen_size():
    return (user32.GetSystemMetrics(SM_CXVIRTUALSCREEN),
            user32.GetSystemMetrics(SM_CYVIRTUALSCREEN),
            user32.GetSystemMetrics(SM_XVIRTUALSCREEN),
            user32.GetSystemMetrics(SM_YVIRTUALSCREEN))


def _abs(x, y):
    w, h, ox, oy = screen_size()
    nx = int(round((x - ox) * 65535.0 / max(1, w - 1)))
    ny = int(round((y - oy) * 65535.0 / max(1, h - 1)))
    return max(0, min(65535, nx)), max(0, min(65535, ny))


def move(x, y):
    nx, ny = _abs(x, y)
    return _send(_mi(nx, ny, MOUSEEVENTF_MOVE | MOUSEEVENTF_ABSOLUTE))


def click(x, y, settle=0.05):
    move(x, y)
    time.sleep(settle)
    _send(_mi(flags=MOUSEEVENTF_LEFTDOWN))
    time.sleep(0.02)
    _send(_mi(flags=MOUSEEVENTF_LEFTUP))
    return True


def scroll(n, x=None, y=None):
    """n>0 向上，n<0 向下（一格=120）"""
    if x is not None and y is not None:
        move(x, y)
        time.sleep(0.03)
    return _send(_mi(flags=MOUSEEVENTF_WHEEL, data=int(n) * 120))


def key(vk, up=False):
    return _send(_ki(vk=vk, flags=KEYEVENTF_KEYUP if up else 0))


def tap(vk, settle=0.03):
    key(vk)
    time.sleep(0.02)
    key(vk, up=True)
    time.sleep(settle)


def type_text(s):
    """Unicode 逐字（不依赖输入法）"""
    for ch in s:
        u = ch.encode("utf-16-le")
        for k in range(0, len(u), 2):
            code = int.from_bytes(u[k:k + 2], "little")
            _send(_ki(scan=code, flags=KEYEVENTF_UNICODE))
            _send(_ki(scan=code, flags=KEYEVENTF_UNICODE | KEYEVENTF_KEYUP))
        time.sleep(0.01)


def list_windows(keyword=""):
    """→ [(hwnd, 标题, 类名, 前台?)]"""
    out = []
    fg = user32.GetForegroundWindow()

    @ctypes.WINFUNCTYPE(ctypes.c_bool, wintypes.HWND, wintypes.LPARAM)
    def cb(hwnd, _l):
        if not user32.IsWindowVisible(hwnd):
            return True
        ln = user32.GetWindowTextLengthW(hwnd)
        if ln <= 0:
            return True
        buf = ctypes.create_unicode_buffer(ln + 2)
        user32.GetWindowTextW(hwnd, buf, ln + 2)
        cls = ctypes.create_unicode_buffer(256)
        user32.GetClassNameW(hwnd, cls, 256)
        t = buf.value
        if keyword and keyword.lower() not in t.lower():
            return True
        r = wintypes.RECT()
        user32.GetWindowRect(hwnd, ctypes.byref(r))
        out.append({"hwnd": int(hwnd), "title": t, "cls": cls.value,
                    "rect": (r.left, r.top, r.right, r.bottom),
                    "fg": int(hwnd) == int(fg or 0)})
        return True

    user32.EnumWindows(cb, 0)
    return out


def focus_window(keyword="", cls=""):
    for w in list_windows(keyword):
        if cls and cls.lower() not in w["cls"].lower():
            continue
        h = w["hwnd"]
        if user32.IsIconic(h):
            user32.ShowWindow(h, SW_RESTORE)
        user32.SetForegroundWindow(h)
        time.sleep(0.35)
        return w
    return None


def grab(path, rect=None):
    """截屏（默认整虚拟桌面；rect=(l,t,r,b) 可只截窗口）→ png"""
    import subprocess
    if rect:
        l, t, r, b = rect
    else:
        w, h, ox, oy = screen_size()
        l, t, r, b = ox, oy, ox + w, oy + h
    ps = (
        "Add-Type -AssemblyName System.Drawing;"
        f"$l={l};$t={t};$w={r - l};$h={b - t};"
        "$bmp=New-Object System.Drawing.Bitmap($w,$h);"
        "$g=[System.Drawing.Graphics]::FromImage($bmp);"
        "$g.CopyFromScreen($l,$t,0,0,$bmp.Size);"
        f"$bmp.Save('{path}',[System.Drawing.Imaging.ImageFormat]::Png);"
        "$g.Dispose();$bmp.Dispose();'ok'"
    )
    r = subprocess.run(["powershell", "-NoProfile", "-Command", ps],
                       capture_output=True, text=True)
    return r.stdout.strip() == "ok", r.stderr.strip()[:200]


if __name__ == "__main__":
    print("虚拟桌面:", screen_size())
    for w in list_windows()[:12]:
        print(f"  {w['hwnd']:>10d} fg={w['fg']!s:5s} {w['cls'][:26]:26s} {w['title'][:60]}")
    ok, err = grab(r"C:\Users\user\AppData\Local\Temp\opencode\screen.png")
    print("截屏:", ok, err)
